import{_ as r,p as a,q as n,s as t,R as e,t as o,Y as s,n as c}from"./framework-e1bed10d.js";const h="/my-blog/assets/047_01-927dea31.png",p={},i=t("h1",{id:"信贷核算的科目体系",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#信贷核算的科目体系","aria-hidden":"true"},"#"),e(" 信贷核算的科目体系")],-1),_={href:"https://mp.weixin.qq.com/s?__biz=MzIzNzQ5NjU5NQ==&mid=2247485069&idx=1&sn=6dc8b97b9e6a7adbaeee28cf92b660ff&chksm=e8c6f6f1dfb17fe72faf8a36fe738d38cd1b457177782822ced01d6ddda20df5044a72c58565",target:"_blank",rel:"noopener noreferrer"},l=s('<hr><p>二、信贷核算的科目体系</p><h3 id="一-科目怎么来的" tabindex="-1"><a class="header-anchor" href="#一-科目怎么来的" aria-hidden="true">#</a> （一）科目怎么来的</h3><p>科目不是程序员定义的，是核算的产品维度：什么产品、什么费用代码、记到哪个科目，由核算产品配置决定。比如费用代码“1-保证金”“14-利息”“2-滞纳金”，分别映射到不同的收入科目。</p><p>科目还讲究分层，当时按五级来命名：一级科目4位，管总贷款；二级科目5位，管贷款形态（正常、逾期、非应计）；三级管期限；四级管归属方（自有还是已转卖）；五级科目13位，管到具体产品。比如“现金贷P001 3个月短期自有正常透支”这个科目，编号就是1001000100010（13位）。分得越细，报表能切的维度越多，但配置和维护也越重，所以每级分到哪，是核算和产品一起定的。</p><p><strong>表6-1 信贷核算的核心科目（简化）</strong></p><table><thead><tr><th><strong>科目大类</strong></th><th><strong>典型科目</strong></th><th><strong>借贷方向</strong></th><th><strong>说明</strong></th></tr></thead><tbody><tr><td>资产类</td><td>发放贷款及垫款</td><td>借方增加</td><td>表内贷款本金，按产品分科目核算</td></tr><tr><td>负债类</td><td>吸收存款、同业存放</td><td>贷方增加</td><td>客户存款、同业拆借等资金来源</td></tr><tr><td>损益类</td><td>利息收入、手续费收入</td><td>贷方增加</td><td>信贷业务产生的收入</td></tr><tr><td>费用类</td><td>利息支出、营业费用</td><td>借方增加</td><td>资金成本、运营成本</td></tr></tbody></table><h3 id="二-表内与表外" tabindex="-1"><a class="header-anchor" href="#二-表内与表外" aria-hidden="true">#</a> （二）表内与表外</h3><p>表内账记在资产负债表里，表外账不体现为资产。资产转让之后，贷款从表内出表，表外要记“表外转让本金”“表外转让应收利息”“表外转让保证金”，资产虽然不在表内了，但债权债务关系还在，必须记录清楚。</p><p>我见过不少系统把“表外”理解成“数据库的表之外”，其实表外是“资产负债表之外”：不出现在资产负债表上的账务。设计上，表内表外用不同的科目体系，一套核算代码里要能同时开两套账。</p><p>科目粒度的选择也是一个设计决策。太粗，比如所有贷款都记在一个本金科目，就无法区分不同产品的经营情况；太细，比如每个产品每个期限都单独设科目，科目表会膨胀到几百个，维护成本很高。通常的做法是按产品大类设一级科目，按担保方式和期限设二级明细，既满足管理需要，又不会太复杂。</p><p>这里有一个容易混的点：核销贷款为什么要转表外？因为贷款核销后，本金已经从准备金里冲掉了，不再是机构的资产，但这笔钱还在催收中，需要在表外记录，收回来的时候再冲回表内。</p><p>科目设置要遵循三个原则。一是合法性，科目名称和编号要符合财政部和监管的规定，不能自己乱编；二是相关性，科目要能反映信贷业务的特点，比如要区分正常本金和逾期本金、区分利息收入和罚息收入；三是稳定性，科目一旦确定就不能频繁变动，否则历史数据无法可比。新增科目要走审批流程，由财务部门确认后才能在系统里配置。</p><p>信贷核算的科目体系可以分成五大类：资产类、负债类、所有者权益类、成本类、损益类。对信贷系统来说，最常用的是资产类和损益类。资产类包括正常本金、逾期本金、应收利息、银行存款等，记录机构有什么；损益类包括利息收入、手续费收入、减值损失等，记录机构赚了什么、亏了什么。</p><p><img src="'+h+'" alt="图片"></p><p><strong>图6-3 信贷核算的科目体系：分层、表内表外与设计原则</strong></p>',16);function f(b,g){const d=c("ExternalLinkIcon");return a(),n("div",null,[i,t("blockquote",null,[t("p",null,[e("公众号：侃西东　·　发布日期：2026-11-02　·　"),t("a",_,[e("微信原文"),o(d)])])]),l])}const u=r(p,[["render",f],["__file","047.html.vue"]]);export{u as default};
